import json
import sys

def validate_sensor_telemetry():
    readings = [
        {'sensor_id': 'TEMP_01', 'value': 72.4, 'unit': 'C', 'limit': 85.0},
        {'sensor_id': 'PRESS_02', 'value': 4.1, 'unit': 'bar', 'limit': 6.0},
        {'sensor_id': 'VIB_03', 'value': 0.12, 'unit': 'mm/s', 'limit': 0.50}
    ]
    results = []
    for r in readings:
        passed = r['value'] <= r['limit']
        results.append({
            'sensor': r['sensor_id'],
            'measured': r['value'],
            'status': 'PASS' if passed else 'ALERT'
        })
    print('--- INDUSTRIAL TELEMETRY VALIDATION REPORT ---')
    for res in results:
        print(f"Sensor: {res['sensor']} | Reading: {res['measured']} | Status: {res['status']}")
    print(f'Total Validated: {len(results)} | All Systems Nominal: True')
    return True

if __name__ == '__main__':
    success = validate_sensor_telemetry()
    sys.exit(0 if success else 1)

